using System;using System.IO;using Newtonsoft.Json.Linq;using GatTelemetry;
class BrandCheck {static void Main(){int count=0;foreach(JObject item in JArray.Parse(File.ReadAllText("RoadBETS2-Telemetria/tests/Brands/casos-teste.json"))){string make=(string)item["make"],expected=(string)item["expected"];if(TruckModelEvidence.BrandKey(make)!=expected)throw new Exception(make);if(VehicleEconomyKey.Resolve(make,"","x")!=expected)throw new Exception("Economy: "+make);count+=2;}if(VehicleEconomyKey.Resolve("Scania","Marcopolo Paradiso","bus")!="onibus")throw new Exception("Bus");foreach(var v in new[]{("Scania","Touring","onibus"),("Volvo","9700 DD","onibus"),("MAN","Lion\u0027s Coach","onibus"),("Scania","R450","scania"),("Volvo","FH","volvo"),("MAN","TGX","man")})if(VehicleEconomyKey.Resolve(v.Item1,v.Item2,"vehicle")!=v.Item3)throw new Exception("Coach: "+v.Item1+" "+v.Item2);var r=new JObject{["game"]=new JObject{["connected"]=true},["truck"]=new JObject{["make"]="SCANIA 124G"}};if(TruckModelEvidence.Read(r).Signature!="brand|scania")throw new Exception("Signature");r["game"]["connected"]=false;if(TruckModelEvidence.Read(r).Signature!="")throw new Exception("Disconnected");Console.WriteLine((count+3)+" verificacoes C# aprovadas.");}}
